import fs from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import logger from '../lib/logger.js'

/**
 * Offline-mode placeholder images.
 *
 * One static PNG exists for every (workflow × source) combination. They are
 * generated by `src/scripts/generatePlaceholders.ts` and committed under
 * `src/assets/placeholders/` so the API has no runtime font dependency.
 *
 *   maze / word-search  → opaque, bordered, with a circle to reveal stretching
 *   cutting             → a filled circle on a transparent background so the
 *                         traced cutting outline can be judged against a known shape
 */

export type PlaceholderWorkflow = 'maze' | 'word-search' | 'cutting'
export type PlaceholderSource   = 'user-uploaded' | 'system-generated'

export const PLACEHOLDER_WORKFLOWS: readonly PlaceholderWorkflow[] = ['maze', 'word-search', 'cutting']
export const PLACEHOLDER_SOURCES:   readonly PlaceholderSource[]   = ['user-uploaded', 'system-generated']

const __dirname  = path.dirname(fileURLToPath(import.meta.url))
const ASSET_DIR  = path.join(__dirname, '..', 'assets', 'placeholders')

const cache = new Map<string, Buffer>()

export function placeholderFileName(workflow: PlaceholderWorkflow, source: PlaceholderSource): string {
  return `${workflow}-${source}.png`
}

export function placeholderPath(workflow: PlaceholderWorkflow, source: PlaceholderSource): string {
  return path.join(ASSET_DIR, placeholderFileName(workflow, source))
}

/** Raw PNG bytes of the placeholder (read once, then served from memory). */
export async function getPlaceholderPng(workflow: PlaceholderWorkflow, source: PlaceholderSource): Promise<Buffer> {
  const file = placeholderFileName(workflow, source)
  const hit = cache.get(file)
  if (hit) return hit

  const buffer = await fs.readFile(placeholderPath(workflow, source))
  cache.set(file, buffer)
  logger.info({ workflow, source, file, byteLength: buffer.length }, 'placeholders: loaded offline placeholder')
  return buffer
}

/** The placeholder as a `data:image/png;base64,…` URL — the form the Icon type carries. */
export async function getPlaceholderDataUrl(workflow: PlaceholderWorkflow, source: PlaceholderSource): Promise<string> {
  const buffer = await getPlaceholderPng(workflow, source)
  return `data:image/png;base64,${buffer.toString('base64')}`
}

/** Which placeholder stands in for a request: a reference photo means "user uploaded". */
export function placeholderSourceFor(referenceImageDataUrl: string | undefined): PlaceholderSource {
  return referenceImageDataUrl ? 'user-uploaded' : 'system-generated'
}
